// --- Sparse-CBOR write (ADR-0042 driver path). ---

// Marshal writes the SoA buffer to w as the sparse-CBOR wire
// format produced through factsschema/dml_cbor. Thin wrapper
// around AppStateRequestBuildEntities — the per-row chain lives there and
// works against any leeway-DML class that structurally satisfies
// AppStateRequestEntityI.
func (c *AppStateRequestColumns) Marshal(w io.Writer) (err error) {
	ent := appStateRequestPool.Get().(*cbdml.InEntityFacts)
	defer appStateRequestPool.Put(ent)
	ent.SetActiveSections(AppStateRequestActiveSections)
	ent.Builder().SetActiveFields(AppStateRequestActiveFields())
	err = AppStateRequestBuildEntities(ent, c)
	if err != nil {
		return
	}
	var recs []*arrowrowcbor.Record
	recs, err = ent.TransferRecords(nil)
	if err != nil {
		err = eh.Errorf("appstaterequest: transfer records: %w", err)
		return
	}
	rb := arrowrowcbor.JoinRecords(recs)
	_, err = w.Write(rb)
	if err != nil {
		err = eh.Errorf("appstaterequest: marshal write: %w", err)
	}
	return
}

// --- Read path (ra-based). ---

// appStateRequestReader composes the readaccess helpers this kind needs.
// Constructed per Unmarshal call; released via defer.
type appStateRequestReader struct {
	EntityId        *ra.ReadAccessFactsPlainEntityIdAttributes
	EntityTimestamp *ra.ReadAccessFactsPlainEntityTimestampAttributes
	Symbol          *ra.ReadAccessFactsTaggedSymbol
	StringArray     *ra.ReadAccessFactsTaggedStringArray
	TextArray       *ra.ReadAccessFactsTaggedTextArray
}

func newAppStateRequestReader() *appStateRequestReader {
	return &appStateRequestReader{
		EntityId:        ra.NewReadAccessFactsPlainEntityIdAttributes(),
		EntityTimestamp: ra.NewReadAccessFactsPlainEntityTimestampAttributes(),
		Symbol:          ra.NewReadAccessFactsTaggedSymbol(),
		StringArray:     ra.NewReadAccessFactsTaggedStringArray(),
		TextArray:       ra.NewReadAccessFactsTaggedTextArray(),
	}
}

func (r *appStateRequestReader) loadFromRecord(rec arrow.Record) (err error) {
	err = r.EntityId.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("appstaterequest: load EntityId: %w", err)
		return
	}
	err = r.EntityTimestamp.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("appstaterequest: load EntityTimestamp: %w", err)
		return
	}
	err = r.Symbol.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("appstaterequest: load Symbol: %w", err)
		return
	}
	err = r.StringArray.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("appstaterequest: load StringArray: %w", err)
		return
	}
	err = r.TextArray.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("appstaterequest: load TextArray: %w", err)
		return
	}
	return
}

func (r *appStateRequestReader) release() {
	if r == nil {
		return
	}
	if r.EntityId != nil {
		r.EntityId.Release()
	}
	if r.EntityTimestamp != nil {
		r.EntityTimestamp.Release()
	}
	if r.Symbol != nil {
		r.Symbol.Release()
	}
	if r.StringArray != nil {
		r.StringArray.Release()
	}
	if r.TextArray != nil {
		r.TextArray.Release()
	}
}

// Unmarshal appends one row to c per entity in rec, projecting
// the boxer.facts columns through factsschema/ra. Thin wrapper
// around AppStateRequestFillFromArrow — the per-row decode lives there.
func (c *AppStateRequestColumns) Unmarshal(rec arrow.Record) (err error) {
	r := newAppStateRequestReader()
	defer r.release()
	err = r.loadFromRecord(rec)
	if err != nil {
		return
	}
	n := r.EntityId.Len()
	err = AppStateRequestFillFromArrow(
		c,
		n,
		r.EntityId.ValueId,
		r.EntityId.ValueNaturalKey,
		r.EntityTimestamp.ValueTs,
		r.Symbol.Attributes, r.Symbol.Memberships,
		r.StringArray.Attributes, r.StringArray.Memberships,
		r.TextArray.Attributes, r.TextArray.Memberships,
	)
	return
}

// --- buscodec.CodecI bridge. ---

// AppStateRequestCodec is the buscodec.CodecI bridge for AppStateRequest. Encodes one row
// through dml_cbor; decodes via cborarrow.Convert + ra-Unmarshal +
// Row(0). Auto-registered in init() so callers using buscodec.Encode
// / Decode route through here instead of the CBOR fallback.
type AppStateRequestCodec struct{}

var _ buscodec.CodecI = (*AppStateRequestCodec)(nil)

// appStateRequestBusCodec is the package-local singleton wired into buscodec.
var appStateRequestBusCodec = &AppStateRequestCodec{}

func (inst *AppStateRequestCodec) Name() (n string) {
	n = "appStateRequest-sparse-cbor"
	return
}

func (inst *AppStateRequestCodec) ContentType() (ct string) {
	ct = "application/x-runtime-facts+rb;kind=appStateRequest"
	return
}

func (inst *AppStateRequestCodec) Encode(v any) (b []byte, err error) {
	var row AppStateRequest
	switch x := v.(type) {
	case AppStateRequest:
		row = x
	case *AppStateRequest:
		if x == nil {
			err = eh.Errorf("appstaterequest: Encode nil *AppStateRequest")
			return
		}
		row = *x
	default:
		err = eh.Errorf("appstaterequest: Encode requires AppStateRequest or *AppStateRequest, got %T", v)
		return
	}
	cols := &AppStateRequestColumns{}
	cols.Append(row)
	var buf bytes.Buffer
	err = cols.Marshal(&buf)
	if err != nil {
		err = eh.Errorf("appstaterequest: Encode marshal: %w", err)
		return
	}
	b = buf.Bytes()
	return
}

func (inst *AppStateRequestCodec) Decode(b []byte, v any) (err error) {
	target, ok := v.(*AppStateRequest)
	if !ok {
		err = eh.Errorf("appstaterequest: Decode requires *AppStateRequest, got %T", v)
		return
	}
	var arrowBuf bytes.Buffer
	err = cborarrow.Convert(bytes.NewReader(b), &arrowBuf)
	if err != nil {
		err = eh.Errorf("appstaterequest: Decode cborarrow: %w", err)
		return
	}
	rd, err := ipc.NewReader(&arrowBuf)
	if err != nil {
		err = eh.Errorf("appstaterequest: Decode ipc reader: %w", err)
		return
	}
	defer rd.Release()
	if !rd.Next() {
		err = eh.Errorf("appstaterequest: Decode expected one Arrow record, got none")
		return
	}
	rec := rd.RecordBatch()
	defer rec.Release()
	cols := &AppStateRequestColumns{}
	err = cols.Unmarshal(rec)
	if err != nil {
		err = eh.Errorf("appstaterequest: Decode unmarshal: %w", err)
		return
	}
	if cols.Len() != 1 {
		err = eb.Build().Int("got", cols.Len()).Errorf("appstaterequest: Decode expected 1 row")
		return
	}
	*target = cols.Row(0)
	return
}
